function historyRows(){const q=normalizePlate(historySearch),vs=state.visits.filter(v=>(historyStatus==='all'||v.status===historyStatus)&&(!historyDate||day(v.entry)===historyDate||v.exit&&day(v.exit)===historyDate)&&(!q||normalizePlate(v.plate).includes(q)||String(v.ticket).includes(q))).sort((a,b)=>b.entry-a.entry);return vs.length?`${historyMobile(vs)}<div class="table-wrap"><table><thead><tr><th>VEHÍCULO / TICKET</th><th>ENTRADA</th><th>SALIDA</th><th>BRUTO</th><th>EXONERADO</th><th>TOTAL</th><th>ESTADO</th><th></th></tr></thead><tbody>${vs.map(v=>`<tr><td><strong>${esc(v.plate)}</strong><small>#${v.ticket} · ${types[v.type]}</small></td><td>${date(v.entry)}<small>${time(v.entry)}</small></td><td>${v.exit?`${date(v.exit)}<small>${time(v.exit)}</small>`:'—'}</td><td>${money(v.exit?v.gross:quote(v).gross)}</td><td>${v.exit?money(v.discount):'—'}<small>${esc(v.reason||'')}</small></td><td><strong>${v.exit?money(v.total):'—'}</strong><small>${esc(v.method||'')}</small></td><td><span class="pill ${v.status==='paid'?'green':v.status==='pending'?'orange':''}">${{inside:'Dentro',paid:'Pagado',pending:'Pendiente'}[v.status]}</span></td><td>${v.status==='inside'?`<button class="mini-button" data-charge="${v.id}">Cobrar</button>`:v.status==='pending'?`<button class="mini-button" data-settle="${v.id}">Registrar pago</button>`:`<button class="text-button" data-receipt="${v.id}">Ver detalle ↗</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Sin movimientos para mostrar','Las entradas y salidas quedarán aquí. Prueba también con otros filtros.','historial');}
function historyPage(){return heading('Tu historial, siempre a mano.','Entradas, salidas, pagos y cada exoneración registrada.','MOVIMIENTOS',`<button class="button outline" data-action="csv">${icon('download')} Exportar CSV</button>`)+`<div class="toolbar"><input type="search" id="history-search" placeholder="Buscar placa o ticket…" aria-label="Buscar en historial" value="${esc(historySearch)}"><select id="history-status" aria-label="Estado">${[['all','Todos los estados'],['inside','Dentro'],['paid','Pagados'],['pending','Pendientes']].map(([k,t])=>`<option value="${k}" ${k===historyStatus?'selected':''}>${t}</option>`).join('')}</select><input id="history-date" type="date" aria-label="Fecha de entrada o salida" value="${esc(historyDate)}"><button class="button outline" data-action="clear-history">Limpiar</button></div><div class="card" id="history-results">${historyRows()}</div><p class="compact-note">La fecha filtra por entrada o salida. El CSV exporta todos los movimientos y la configuración para poder continuar en otro dispositivo.</p>`;}
function ticketsPage(){const s=state.settings,n=nextFree(state);return heading('Un ticket para cada entrada.','Tu numeración empieza en 1. Amplía el talonario cuando lo necesites.','TALONARIO')+`<div class="two-col"><div class="stack">${card('Talonario actual','tickets',`<div class="card-body"><div class="metrics-detail"><div class="detail-line"><span>Rango generado</span><strong>#1 – #${s.ticketEnd}</strong></div><div class="detail-line"><span>Tickets utilizados</span><strong>${state.visits.length}</strong></div><div class="detail-line"><span>Disponibles desde el siguiente</span><strong>${n?s.ticketEnd-n+1:0}</strong></div></div><div class="ticket-preview"><span class="small-label">${esc(s.name)}</span><div class="folio">${n?'#'+String(n).padStart(4,'0'):'—'}</div><p>Siguiente ticket disponible</p></div><form id="ticket-form"><label class="field"><span>¿Cuántos tickets más quieres generar?</span><input name="quantity" type="number" min="1" max="1000000" step="1" value="1000" required><small>Se agregarán después del #${s.ticketEnd}. Los anteriores se conservan.</small></label><button class="button wide">${icon('plus')} Generar más tickets</button></form></div>`)}</div><div class="stack">${card('Imprimir tickets','print',`<div class="card-body"><p class="muted" style="font-size:12px">Para usar boletos de papel, imprime un rango de tu talonario. También puedes guardar como PDF desde la ventana de impresión.</p><form id="print-tickets" class="section-gap"><div class="form-grid"><label class="field"><span>Desde el ticket</span><input name="from" type="number" min="1" max="${s.ticketEnd}" value="${n||1}" required></label><label class="field"><span>Hasta el ticket</span><input name="to" type="number" min="1" max="${s.ticketEnd}" value="${Math.min(s.ticketEnd,(n||1)+49)}" required></label></div><p class="compact-note">Máximo 500 tickets por impresión. Imprimir no los marca como utilizados.</p><button class="button outline wide section-gap">${icon('print')} Preparar impresión</button></form><div class="notice">${icon('info')}<div><strong>¿Tienes un boleto físico distinto?</strong>Puedes adelantar el siguiente número sin borrar el historial.</div></div><form id="next-ticket-form" class="section-gap"><label class="field"><span>Siguiente ticket a utilizar</span><input name="next" type="number" min="1" max="${s.ticketEnd}" step="1" value="${n||s.ticketEnd}" required></label><button class="button secondary wide">Ajustar siguiente número</button><p class="compact-note">Cada número se asigna una sola vez. Si ya fue usado, el sistema lo omite.</p></form></div>`)}</div></div>`;}
function field(label,name,value,attrs='',help=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" ${attrs}>${help?`<small>${help}</small>`:''}</label>`;}
function settingsPage(){const s=state.settings;return heading('A tu manera de trabajar.','Ajusta las tarifas y lleva tus datos contigo.','AJUSTES')+`<div class="two-col"><div class="stack">${card('Tu garaje y tarifas','ajustes',`<div class="card-body"><form id="settings-form">${field('Nombre del garaje','name',s.name,'maxlength="60" required')}<div class="form-grid">${field('Capacidad de vehículos','capacity',s.capacity,'type="number" min="1" max="100000" step="1" required')}<label class="field"><span>Moneda</span><select name="currency">${['S/','$','€','Bs'].map(c=>`<option ${s.currency===c?'selected':''}>${c}</option>`).join('')}</select></label></div><h3 class="section-gap section-title">Tarifas por bloque</h3>${Object.keys(types).map(k=>field(types[k],k,s.rates[k],'type="number" min="0.01" max="100000" step="0.01" required')).join('')}<div class="form-grid"><label class="field"><span>Cobrar por</span><select name="block">${[60,30,15].map(b=>`<option value="${b}" ${s.block===b?'selected':''}>${b===60?'Hora iniciada':b+' minutos iniciados'}</option>`).join('')}</select></label>${field('Tolerancia (min)','tolerance',s.tolerance,'type="number" min="0" max="59" step="1" required')}</div><div class="rule section-gap"><strong>¿Cómo se cobra?</strong><br>Los primeros minutos de tolerancia son gratis. Después se cobra cada bloque iniciado, permitiendo la misma tolerancia al pasar a otro bloque. Ejemplo: S/ 5 por hora y 10 min de tolerancia → 1 h 10 min cuesta S/ 5; 1 h 11 min cuesta S/ 10.</div><p class="compact-note">Las tarifas y tolerancia nuevas se aplican a las próximas entradas. Los vehículos dentro conservan las condiciones con las que ingresaron.</p><div id="settings-error"></div><button class="button wide section-gap">${icon('check')} Guardar ajustes</button></form></div>`)}</div><div class="stack">${card('Tus datos, contigo','shield',`<div class="card-body"><div class="download-card"><span class="icon-box">${icon('download')}</span><div><h3>Copia completa</h3><p>Historial, vehículos dentro y ajustes.<br>Ideal para continuar en otro celular.</p></div><button class="button secondary" data-action="backup">Descargar</button></div><div class="download-card"><span class="icon-box">${icon('historial')}</span><div><h3>Exportar CSV</h3><p>Todos tus registros para Excel.<br>También puedes volver a importarlo.</p></div><button class="button outline" data-action="csv">Exportar</button></div><div class="section-gap"><h3>Continuar desde una copia</h3><p class="compact-note">Importa un respaldo JSON o un CSV de AutoBox. Verás un resumen antes de reemplazar los datos de este dispositivo.</p><label class="button outline wide section-gap" for="import-file">${icon('upload')} Elegir archivo para importar</label><input id="import-file" type="file" accept=".json,.csv,application/json,text/csv" class="sr-only"></div><div class="notice">${icon('info')}<div><strong>Última copia descargada</strong>${state.backupAt?`${date(state.backupAt)} · ${time(state.backupAt)}`:'Aún no has descargado una copia.'}<br>Haz una copia al terminar tu jornada. Los dispositivos no se sincronizan automáticamente.</div></div>${storageError?'<button class="button danger wide section-gap" data-action="recovery">Descargar datos sin procesar</button>':''}</div>`)}${card('Usar sin internet','download',`<div class="card-body"><div class="install-tip">${icon('shield')}<div><h3>Tu garaje sigue funcionando</h3><p id="offline-status">${location.protocol==='file:'?'Versión portátil: guarda este archivo y ábrelo en tu navegador.':'Preparando disponibilidad sin conexión…'}</p></div></div><p class="compact-note">Abre la web una vez con internet y espera a que indique «Disponible sin conexión». En el celular, agrega la web a tu pantalla de inicio desde el menú del navegador (en iPhone: Compartir → Añadir a pantalla de inicio).</p><button class="button secondary wide section-gap" data-action="install">${icon('plus')} Instalar o ver instrucciones</button><div class="notice">${icon('info')}<div><strong>Guarda también una copia portátil</strong>Un archivo HTML que puedes conservar y abrir desde un navegador compatible. Para celular, la instalación desde la web es la opción más sencilla.</div></div><a class="button outline wide section-gap" href="./AutoBox-portatil.html" download>${icon('download')} Descargar versión portátil</a><p class="compact-note">Usa siempre el mismo navegador y la misma dirección. Borrar los datos del navegador o usar modo privado puede eliminar los registros; guarda respaldos fuera de la app.</p></div>`)}</div></div>`;}
function render(){if(!navItems.some(([k])=>k===page))page='entrada';const nav=navItems.map(([k,t])=>`<a href="#${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${icon(k)}<span>${t}</span>${k==='entrada'?`<span class="nav-count">${inside().length}</span>`:''}</a>`).join('');$('#navigation').innerHTML=nav;$('#mobile-nav').innerHTML=nav.replace(/<span class="nav-count">.*?<\/span>/,'');$('#garage-name').textContent=state.settings.name;$('#page-name').textContent=navItems.find(([k])=>k===page)[1];$('#header-date').textContent=new Date().toLocaleDateString('es-PE',{day:'numeric',month:'short',year:'numeric'});$('#main').innerHTML=(storageError?`<div class="error">${storageError}</div>`:'')+({entrada:entryPage,salida:exitPage,resumen:dashboard,historial:historyPage,tickets:ticketsPage,ajustes:settingsPage}[page]());connectivity();}
function errorAt(id,message){const el=$(id);if(el)el.innerHTML=`<div class="error" role="alert">${esc(message)}</div>`;else toast(message);}
function showDialog(title,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button data-action="close-dialog" aria-label="Cerrar">×</button></div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
let charge=null;
function chargeDialog(id){const v=state.visits.find(v=>v.id===id);if(!v||v.exit)return;const exit=Date.now(),q=quote(v,exit);charge={id,exit,...q};showDialog('Revisar y cobrar salida',`<div class="dialog-plate"><div><strong>${esc(v.plate)}</strong><p>${types[v.type]} · Ticket #${v.ticket}</p></div><span class="pill">${duration(q.minutes)}</span></div><div class="metrics-detail"><div class="detail-line"><span>Entrada</span><strong>${date(v.entry)} · ${time(v.entry)}</strong></div><div class="detail-line"><span>Salida</span><strong>${date(exit)} · ${time(exit)}</strong></div><div class="detail-line"><span>Tarifa de esta entrada</span><strong>${money(v.rate)} / ${v.block} min</strong></div><div class="detail-line"><span>Tolerancia</span><strong>${v.tolerance} minutos</strong></div><div class="detail-line"><span>${q.blocks} ${q.blocks===1?'bloque cobrado':'bloques cobrados'}</span><strong>${money(q.gross)}</strong></div></div><form id="charge-form"><div class="waive-options"><button type="button" class="button secondary" data-action="waive-fraction" ${q.blocks<2?'disabled':''}>Perdonar última fracción</button><button type="button" class="button outline" data-action="manual-discount">Otro descuento</button></div><div id="discount-area" class="discount-area" hidden><label class="field"><span>Monto a exonerar (${esc(state.settings.currency)})</span><input id="discount" type="number" min="0" max="${q.gross}" step="0.01" value="0"></label><label class="field"><span>Motivo de la exoneración</span><input id="discount-reason" maxlength="300" placeholder="Ej. Cortesía por 5 minutos extra"></label></div><div class="charge-hero"><span>TOTAL A COBRAR</span><strong id="charge-total">${money(q.gross)}</strong><small id="discount-summary">Sin exoneración</small></div><label class="field"><span>Medio de pago</span><select id="payment-method">${['Efectivo','Yape / Plin','Tarjeta','Transferencia'].map(m=>`<option>${m}</option>`).join('')}</select></label><div class="status-choice"><label><input name="payment-status" type="radio" value="paid" checked> Ya pagó</label><label><input name="payment-status" type="radio" value="pending"> Dejar pendiente</label></div><p class="compact-note">El importe se calcula hasta la hora de salida indicada. Confirma para registrar la salida y liberar el espacio.</p><div id="charge-error"></div><button class="button big wide section-gap">${icon('check')} Confirmar salida</button></form>`);}
function updateDiscount(){const discount=Number($('#discount').value);$('#charge-total').innerHTML=money(Math.max(0,charge.gross-(Number.isFinite(discount)?discount:0)));$('#discount-summary').textContent=discount>0?`Exoneración: ${state.settings.currency} ${discount.toFixed(2)}`:'Sin exoneración';}
function receipt(id){const v=state.visits.find(v=>v.id===id);if(!v)return;showDialog(v.exit?'Detalle del movimiento':'Entrada registrada',`<div class="dialog-plate"><div><strong>${esc(v.plate)}</strong><p>${types[v.type]} · Ticket #${v.ticket}</p></div><span class="pill ${v.status==='paid'?'green':v.status==='pending'?'orange':''}">${{inside:'Dentro',paid:'Pagado',pending:'Pendiente'}[v.status]}</span></div><div class="metrics-detail"><div class="detail-line"><span>Entrada</span><strong>${date(v.entry)} · ${time(v.entry)}</strong></div>${v.exit?`<div class="detail-line"><span>Salida</span><strong>${date(v.exit)} · ${time(v.exit)}</strong></div><div class="detail-line"><span>Estancia</span><strong>${duration((v.exit-v.entry)/60000)}</strong></div><div class="detail-line"><span>Importe original</span><strong>${money(v.gross)}</strong></div><div class="detail-line"><span>Exonerado</span><strong>${money(v.discount)}</strong></div>${v.reason?`<div class="notice">${icon('info')}<div><strong>Motivo</strong>${esc(v.reason)}</div></div>`:''}<div class="detail-line total"><span>Total</span><strong>${money(v.total)}</strong></div><div class="detail-line"><span>Medio de pago</span><strong>${esc(v.method)}</strong></div>${v.paidAt?`<div class="detail-line"><span>Pago registrado</span><strong>${date(v.paidAt)} · ${time(v.paidAt)}</strong></div>`:''}`:`<div class="detail-line"><span>Tarifa</span><strong>${money(v.rate)} / ${v.block} min</strong></div>`}</div><button class="button outline wide section-gap" data-print-receipt="${v.id}">${icon('print')} Imprimir comprobante</button>`);}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function backup(csv=false){const next=structuredClone(state);next.backupAt=Date.now();download(`AutoBox-${today()}-${time(Date.now()).replace(':','-')}.${csv?'csv':'json'}`,csv?toCSV(next):JSON.stringify(next,null,2),csv?'text/csv;charset=utf-8':'application/json');persist(next);toast('Copia descargada. Guárdala fuera de este dispositivo.');if(page==='ajustes')render();}
function printDocument(content,title){const frame=document.createElement('iframe');frame.style.cssText='position:fixed;left:-9999px;width:1px;height:1px';document.body.append(frame);frame.srcdoc=`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:14px Arial;color:#222;margin:24px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.ticket{border:1px dashed #777;padding:22px 12px;text-align:center;break-inside:avoid}.number{font-size:36px;font-weight:bold;margin:14px}.label{font-size:11px;margin:9px}h1{font-size:20px}p{line-height:1.8}.receipt{max-width:340px;margin:auto;border:1px dashed #aaa;padding:25px}@media print{@page{size:A4;margin:10mm}body{margin:0}}</style></head><body>${content}</body></html>`;frame.onload=()=>{setTimeout(()=>{frame.contentWindow.focus();frame.contentWindow.print();},100);};setTimeout(()=>frame.remove(),180000);}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go){go(b.dataset.go);return;}if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('.category').forEach(x=>{x.classList.toggle('selected',x.dataset.category===category);x.setAttribute('aria-pressed',String(x.dataset.category===category));});return;}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x.dataset.filter===filter));$('#vehicle-list').innerHTML=vehicleList();return;}if(b.dataset.charge){chargeDialog(b.dataset.charge);return;}if(b.dataset.receipt){receipt(b.dataset.receipt);return;}if(b.dataset.settle){const v=state.visits.find(v=>v.id===b.dataset.settle);if(!v||v.status!=='pending')return;showDialog('Registrar pago pendiente',`<p><strong>${esc(v.plate)} · #${v.ticket}</strong></p><div class="charge-hero"><span>IMPORTE PENDIENTE</span><strong>${money(v.total)}</strong></div><form id="settle-form" data-id="${v.id}"><label class="field"><span>Medio de pago</span><select name="method">${['Efectivo','Yape / Plin','Tarjeta','Transferencia'].map(m=>`<option>${m}</option>`).join('')}</select></label><p class="compact-note">El ingreso se registrará en la caja de hoy.</p><button class="button wide section-gap">Confirmar pago recibido</button></form>`);return;}if(b.dataset.printReceipt){const v=state.visits.find(v=>v.id===b.dataset.printReceipt);printDocument(`<div class="receipt"><h1>${esc(state.settings.name)}</h1><p>COMPROBANTE DE ESTACIONAMIENTO<br>Ticket <strong>#${v.ticket}</strong></p><h1>${esc(v.plate)}</h1><p>${types[v.type]}<br>Entrada: ${esc(new Date(v.entry).toLocaleString('es-PE'))}${v.exit?`<br>Salida: ${esc(new Date(v.exit).toLocaleString('es-PE'))}<br>Bruto: ${money(v.gross)}<br>Exonerado: ${money(v.discount)}<br>Motivo: ${esc(v.reason||'—')}<br><strong>Total: ${money(v.total)}</strong><br>Estado: ${v.status==='paid'?'Pagado':'Pendiente'} · ${esc(v.method)}`:'<br>Conserva tu ticket.'}</p><p>Gracias por tu visita.</p></div>`,'Ticket '+v.ticket);return;}
 switch(b.dataset.action){case 'clear-plate':$('#plate').value='';$('#plate').focus();break;case 'backup':backup();break;case 'csv':backup(true);break;case 'close-dialog':$('#dialog').close();break;case 'manual-discount':$('#discount-area').hidden=false;$('#discount').focus();break;case 'waive-fraction':{const v=state.visits.find(v=>v.id===charge.id);$('#discount-area').hidden=false;$('#discount').value=v.rate;$('#discount-reason').value='Cortesía: última fracción exonerada';updateDiscount();break;}case 'clear-history':historySearch='';historyStatus='all';historyDate='';render();break;case 'confirm-import':{if(!pendingImport)return;const prior=state;if(storageError)download('AutoBox-recuperacion-previa.txt',localStorage.getItem(KEY)||'Sin datos','text/plain');download(`AutoBox-antes-de-importar-${today()}.json`,JSON.stringify(prior,null,2),'application/json');if(persist(pendingImport,true)){pendingImport=null;lastEntry=null;$('#dialog').close();render();toast('Datos importados. Ya puedes continuar.');}break;}case 'recovery':try{download('AutoBox-recuperacion.txt',localStorage.getItem(KEY)||'Sin datos','text/plain');}catch{toast('El navegador no permite leer el almacenamiento.');}break;case 'install':if(installEvent){installEvent.prompt();installEvent=null;}else showDialog('Instalar AutoBox',`<p>En <strong>Android</strong>, abre el menú del navegador y elige «Instalar aplicación» o «Agregar a pantalla de inicio».</p><p class="section-gap">En <strong>iPhone</strong>, abre en Safari, toca Compartir y luego «Añadir a pantalla de inicio».</p><div class="notice">${icon('info')}<div>Abre la app una vez con internet y espera «Disponible sin conexión» antes de desconectarte. Guarda un respaldo para pasar los datos a otro equipo.</div></div>`);break;}
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='plate')t.value=t.value.toUpperCase().replace(/[^A-Z0-9-]/g,'');if(t.id==='vehicle-search'){search=t.value;$('#vehicle-list').innerHTML=vehicleList();}if(t.id==='exit-search'){exitSearch=t.value;$('#exit-list').innerHTML=vehicleList();}if(t.id==='history-search'){historySearch=t.value;$('#history-results').innerHTML=historyRows();}if(t.id==='discount')updateDiscount();});
document.addEventListener('change',async e=>{if(e.target.id==='history-status'){historyStatus=e.target.value;$('#history-results').innerHTML=historyRows();}if(e.target.id==='history-date'){historyDate=e.target.value;$('#history-results').innerHTML=historyRows();}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('El archivo supera 30 MB.');const text=await file.text();pendingImport=file.name.toLowerCase().endsWith('.csv')?fromCSV(text):validate(JSON.parse(text));const ins=pendingImport.visits.filter(v=>!v.exit).length;showDialog('Revisar importación',`<p>Archivo: <strong>${esc(file.name)}</strong></p><div class="metrics-detail section-gap"><div class="detail-line"><span>Garaje</span><strong>${esc(pendingImport.settings.name)}</strong></div><div class="detail-line"><span>Movimientos</span><strong>${pendingImport.visits.length}</strong></div><div class="detail-line"><span>Vehículos dentro</span><strong>${ins}</strong></div><div class="detail-line"><span>Tickets generados</span><strong>${pendingImport.settings.ticketEnd}</strong></div></div><div class="notice warn">${icon('info')}<div><strong>Se reemplazarán los datos actuales</strong>Actualmente tienes ${state.visits.length} movimientos. Se descargará una copia de tus datos actuales antes de importar. Los registros no se mezclan.</div></div><button class="button wide section-gap" data-action="confirm-import">Reemplazar e importar copia</button>`);}catch(error){pendingImport=null;toast('No se importó: '+error.message);}e.target.value='';}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='entry-form'){const plate=String(f.get('plate')).trim().toUpperCase(),n=nextFree(state);if(!/^[A-Z0-9-]{3,12}$/.test(plate)||normalizePlate(plate).length<3){errorAt('#entry-error','Ingresa una placa válida de 3 a 12 caracteres.');return;}if(inside().some(v=>normalizePlate(v.plate)===normalizePlate(plate))){errorAt('#entry-error','Esa placa ya está dentro. Búscala en la lista para registrar su salida.');return;}if(inside().length>=state.settings.capacity){errorAt('#entry-error','El garaje está lleno. Registra una salida o ajusta la capacidad.');return;}if(!n){toast('Genera más tickets en Talonario.');return;}const s=state.settings,v={id:globalThis.crypto?.randomUUID?.()||`v-${Date.now()}-${Math.random().toString(36).slice(2)}`,ticket:n,plate,type:category,entry:Date.now(),exit:null,rate:s.rates[category],tolerance:s.tolerance,block:s.block,status:'inside'};if(commit(x=>{x.visits.push(v);x.settings.nextTicket=n+1;})){lastEntry=v;render();$('#plate')?.focus();toast(`Entrada registrada · ${plate} · Ticket #${n}`);}}
 if(form.id==='charge-form'){const v=state.visits.find(v=>v.id===charge.id);if(!v||v.exit){errorAt('#charge-error','Esta salida ya fue registrada.');return;}const discount=Number($('#discount').value),reason=$('#discount-reason').value.trim(),status=f.get('payment-status'),method=$('#payment-method').value;if(!Number.isFinite(discount)||discount<0||discount>charge.gross){errorAt('#charge-error','La exoneración debe estar entre cero y el importe original.');return;}if(discount>0&&!reason){errorAt('#charge-error','Escribe el motivo de la exoneración para que quede registrado.');return;}if(commit(x=>Object.assign(x.visits.find(v=>v.id===charge.id),{exit:charge.exit,gross:charge.gross,discount:Math.round(discount*100)/100,reason:discount>0?reason:'',total:Math.round((charge.gross-discount)*100)/100,status,method,paidAt:status==='paid'?Date.now():null}))){$('#dialog').close();lastEntry=null;render();toast(status==='paid'?'Pago y salida registrados.':'Salida registrada con pago pendiente.');}}
 if(form.id==='settings-form'){const s={...state.settings,name:String(f.get('name')).trim(),capacity:+f.get('capacity'),currency:f.get('currency'),rates:Object.fromEntries(Object.keys(types).map(k=>[k,+f.get(k)])),block:+f.get('block'),tolerance:+f.get('tolerance')};try{if(!s.name)throw Error('Escribe el nombre de tu garaje.');if(s.currency!==state.settings.currency&&state.visits.length)throw Error('Con movimientos registrados, conserva la moneda actual para no mezclar los importes del historial.');validate({...state,settings:s});if(persist({...state,settings:s})){render();toast('Ajustes guardados para las próximas entradas.');}}catch(error){errorAt('#settings-error',error.message);}}
 if(form.id==='ticket-form'){const qty=+f.get('quantity');if(!Number.isInteger(qty)||qty<1||qty>1000000||state.settings.ticketEnd+qty>10000000){toast('Introduce una cantidad entera válida; máximo total: 10 millones.');return;}if(commit(x=>x.settings.ticketEnd+=qty)){render();toast(`${qty} tickets nuevos generados.`);}}
 if(form.id==='next-ticket-form'){const n=+f.get('next');if(!Number.isInteger(n)||n<1||n>state.settings.ticketEnd){toast('El número debe estar dentro del talonario.');return;}if(commit(x=>x.settings.nextTicket=n)){render();toast('Siguiente número ajustado.');}}
 if(form.id==='print-tickets'){const from=+f.get('from'),to=+f.get('to');if(!Number.isInteger(from)||!Number.isInteger(to)||from<1||to<from||to>state.settings.ticketEnd||to-from>=500){toast('Elige un rango válido de hasta 500 tickets.');return;}printDocument(`<div class="grid">${Array.from({length:to-from+1},(_,i)=>`<div class="ticket"><strong>${esc(state.settings.name)}</strong><div class="label">TICKET DE ESTACIONAMIENTO</div><div class="number">#${String(from+i).padStart(4,'0')}</div><div class="label">Placa: __________________</div><div class="label">Entrada: ________________</div><div class="label">Conserva este ticket para tu salida.</div></div>`).join('')}</div>`,'AutoBox · Tickets');}
 if(form.id==='settle-form'){const v=state.visits.find(v=>v.id===form.dataset.id);if(v?.status==='pending'&&commit(x=>Object.assign(x.visits.find(v=>v.id===form.dataset.id),{status:'paid',paidAt:Date.now(),method:f.get('method')}))){$('#dialog').close();render();toast('Pago registrado en la caja de hoy.');}}
});
let offlineReady=false;function connectivity(){const el=$('#connectivity');el.innerHTML=`<span class="dot"></span> ${location.protocol==='file:'?'Versión portátil':offlineReady?'Disponible sin conexión':navigator.onLine?'En este dispositivo':'Sin conexión'}`;const status=$('#offline-status');if(status)status.textContent=location.protocol==='file:'?'Versión portátil guardada en este archivo.':offlineReady?'Disponible sin conexión. Ya puedes abrirla sin internet.':'Preparando disponibilidad sin conexión…';}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1);render();window.scrollTo(0,0);});window.addEventListener('online',connectivity);window.addEventListener('offline',connectivity);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
window.addEventListener('storage',e=>{if(e.key===KEY){try{state=validate(JSON.parse(e.newValue));storageError='';lastEntry=null;$('#dialog').close();render();toast('Datos actualizados desde otra pestaña.');}catch{toast('Los datos cambiaron en otra pestaña. Recarga antes de continuar.');}}});
render();
if('serviceWorker' in navigator&&location.protocol!=='file:'){
 const hadController=!!navigator.serviceWorker.controller;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(hadController)location.reload();});
 navigator.serviceWorker.register('./sw.js').then(async()=>{await navigator.serviceWorker.ready;offlineReady=!!(await caches.match(new URL('./index.html',location.href)));connectivity();}).catch(()=>{const status=$('#offline-status');if(status)status.textContent='No se pudo preparar el modo sin conexión. Abre la web con internet y vuelve a intentarlo.';});
}
setInterval(()=>{if($('#dialog').open)return;if(page==='entrada'&&$('#vehicle-list'))$('#vehicle-list').innerHTML=vehicleList();if(page==='salida'&&$('#exit-list'))$('#exit-list').innerHTML=vehicleList();},30000);
function historyMobile(vs){return `<div class="history-mobile">${vs.map(v=>`<article class="history-item"><div class="history-item-top"><div><strong>${esc(v.plate)}</strong><small>#${v.ticket} · ${types[v.type]}</small></div><span class="pill ${v.status==='paid'?'green':v.status==='pending'?'orange':''}">${{inside:'Dentro',paid:'Pagado',pending:'Pendiente'}[v.status]}</span></div><div class="history-times"><span>Entrada<strong>${date(v.entry)} · ${time(v.entry)}</strong></span><span>Salida<strong>${v.exit?`${date(v.exit)} · ${time(v.exit)}`:'En el garaje'}</strong></span></div>${v.discount>0?`<div class="history-discount">Exonerado: ${money(v.discount)}<small>${esc(v.reason)}</small></div>`:''}<div class="history-item-bottom"><div><span>${v.exit?'Total':'Estimado actual'}</span><strong>${money(v.exit?v.total:quote(v).gross)}</strong></div>${v.status==='inside'?`<button class="button secondary" data-charge="${v.id}">Cobrar salida</button>`:v.status==='pending'?`<button class="button secondary" data-settle="${v.id}">Registrar pago</button>`:`<button class="button outline" data-receipt="${v.id}">Ver detalle</button>`}</div></article>`).join('')}</div>`;}




